def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if len(alive) == 0:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    cindy_prev = None
    urgent_opps = 0
    rich_opps = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if oid == 'Cindy' and bid is not None:
            cindy_prev = float(bid)
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0)) <= 3:
            urgent_opps += 1
        if float(opp.get('budget', 0)) >= DAILY_SALARY * 6:
            rich_opps += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.6
    elif hp <= 6:
        danger += 0.25
    danger += min(0.8, no_water_days * 0.35)

    base = DAILY_SALARY * (0.34 + 0.22 * scarcity + 0.28 * danger)

    if cindy_prev is not None:
        if danger >= 0.9 or (scarcity >= 0.6 and hp <= 5):
            target = cindy_prev + 2.0
            base = max(base, target)
        elif cindy_prev >= 120:
            base = min(base, DAILY_SALARY * 0.52)
        elif cindy_prev >= 95:
            base = max(base, DAILY_SALARY * 0.58)

    if highest_prev > 0:
        if highest_prev <= 70:
            base = max(base, highest_prev + 1.25)
        elif highest_prev >= 115 and danger < 0.9:
            base = min(base, DAILY_SALARY * 0.5)
        elif danger >= 0.9:
            base = max(base, highest_prev + 1.5)
        else:
            base = max(base, avg_prev * 0.72)

    if urgent_opps >= 2 and danger < 0.9:
        base *= 0.9
    if rich_opps >= 2 and scarcity >= 0.5:
        base *= 1.08

    if day >= 8:
        base *= 1.08
    if day >= 9 and hp <= 5:
        base *= 1.15

    reserve = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0:
        reserve = min(budget * 0.55, days_left * DAILY_SALARY * 0.38)

    cap = budget - reserve
    if danger >= 0.9:
        cap = budget
    elif cap < DAILY_SALARY * 0.25:
        cap = min(budget, DAILY_SALARY * 0.45)

    bid = min(base, cap, budget)

    if danger >= 1.2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.95, highest_prev + 2.0 if highest_prev > 0 else 0.0))
    elif hp <= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.88))

    min_bid = 1.0 if budget >= 1.0 else budget
    if bid < min_bid:
        bid = min_bid

    if bid > budget:
        bid = budget
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 40.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0

    # Aggressive bidding if HP is low, otherwise competitive with market
    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max(avg_prev * 1.1, 90.0))
    else:
        bid = min(my_status['budget'], max(avg_prev * 0.95, 75.0))

    # Adjust for supply scarcity
    if supply < 18:
        bid += 15.0

    return float(min(my_status['budget'], bid))
